        a=random.randrange(len(data)); b=random.randrange(a,len(data)+1); data=data[a:b]
    if len(data)>5000: data=data[:5000]
    for _ in range(random.randint(1,30)):
        op=random.randrange(8)
        if op==0 and data: data[random.randrange(len(data))]=random.randrange(256)
        elif op==1 and len(data)<10000:
            pos=random.randrange(len(data)+1); data[pos:pos]=os.urandom(random.randint(1,16))
        elif op==2 and data:
            pos=random.randrange(len(data)); del data[pos:pos+random.randint(1,16)]
        elif op==3 and data and len(data)<10000:
            pos=random.randrange(len(data)); seg=data[max(0,pos-random.randint(1,50)):pos]; data[pos:pos]=seg
        elif op==4:
            pos=random.randrange(len(data)+1); val=random.choice([0,1,2,3,4,5,7,8,15,16,31,32,63,64,127,128,129,255,256,257,65535,65536,2**31-1,2**32-1]); data[pos:pos+4]=val.to_bytes(4,'little')
        elif op==5 and data:
            pos=random.randrange(len(data)); data[pos:pos+1]=random.choice([b'\0',b'\xff',b'\n',b'\t',b':',b',',b'B',b'C',b'Z'])
        elif op==6 and len(data)<10000:
            data += os.urandom(random.randint(1,32))
        elif op==7:
            data[:0]=random.choice([b'CRAM\x03\x00',b'BAM\1',b'BCF\2\2',b'@HD\t',b'##fileformat=VCF'])
    path='/tmp/mut.bin'; open(path,'wb').write(data)
    try:
        r=subprocess.run(['/tmp/hts_open_asan',path],stdout=subprocess.DEVNULL,stderr=subprocess.PIPE,env=env,timeout=.3)
    except subprocess.TimeoutExpired:
        continue
    if r.returncode != 0:
        err=r.stderr.decode('latin1','ignore')
        if 'ERROR: AddressSanitizer' in err:
            out=f'/workspace/poc_found_{i}.bin'; open(out,'wb').write(data)
            print('FOUND',i,out,'len',len(data),'ret',r.returncode); print(err[:6000]); sys.exit(0)
    if i and i%5000==0: print('iter',i,'time',time.time()-start)
print('none')
